import { expect, jest, vi, setSystemTime } from "bun:test";
import { setTimeout as nodeTimeout, clearTimeout as nodeClear, setInterval as nodeInterval } from "node:timers";
import { setTimeout as promisedTimeout } from "node:timers/promises";
import { AsyncLocalStorage } from "node:async_hooks";

const OriginalDate = Date;
const originalNow = Date.now;
const previous = new Date(0);
const realBefore = Date.now();
const realTimer = new Promise<string>(resolve => setTimeout(() => resolve("real"), 1));
const formatter = new Intl.DateTimeFormat("en-US", { timeZone: "UTC" });
const format = formatter.format.bind(formatter);
expect(jest.useFakeTimers({ now: new Date("2000-01-01T00:00:00Z") })).toBe(jest);
expect(Date).toBe(OriginalDate);
expect(Date.now).toBe(originalNow);
expect(previous instanceof Date).toBe(true);
expect(Date()).toBe(new Date().toString());
expect(format()).toBe("1/1/2000");
expect(new Intl.DateTimeFormat("en-US", { timeZone: "UTC" }).formatToParts().find(p => p.type === "year")?.value).toBe("2000");
expect(Object.hasOwn(setTimeout, "clock")).toBe(true);
expect(new Date(1999, 11, 31).getFullYear()).toBe(1999);
expect(Date.parse("2000-01-01T00:00:00Z")).toBe(946684800000);
expect(Date.UTC(2000, 0, 1)).toBe(946684800000);
expect(new Date(undefined).getTime()).toBeNaN();
class SubDate extends Date { label() { return "subclass"; } }
expect(new SubDate().label()).toBe("subclass");
expect(new SubDate().getTime()).toBe(Date.now());
expect(jest.now()).toBe(946684800000);
expect(vi.now()).toBe(jest.now());
expect(performance.now()).toBe(0);

const events: string[] = [];
const storage = new AsyncLocalStorage<string>();
storage.run("timer-context", () => nodeTimeout((value) => events.push(`${value}:${storage.getStore()}`), 5, "first"));
const cancelled = setTimeout(() => { throw new Error("cancelled timeout fired"); }, 1);
nodeClear(Number(cancelled));
setTimeout(() => events.push("second"), 5);
const refreshed = setTimeout(() => events.push("refresh"), 3);
expect(refreshed.unref().hasRef()).toBe(false);
expect(refreshed.ref().hasRef()).toBe(true);
vi.advanceTimersByTime(2);
refreshed.refresh();
expect(jest.getTimerCount()).toBe(3);
vi.advanceTimersByTime(3);
expect(events).toEqual(["first:timer-context", "second", "refresh"]);
refreshed.refresh();
vi.advanceTimersByTime(3);
expect(events.at(-1)).toBe("refresh");
expect(jest.getTimerCount()).toBe(0);
expect(Date.now()).toBe(946684800008);
expect(process.hrtime.bigint()).toBe(8000000n);
expect(performance.timeOrigin + performance.now()).toBe(Date.now());

let intervals = 0;
const interval = nodeInterval(() => {
  intervals++;
  if (intervals === 3) clearInterval(interval);
}, 2);
vi.runAllTimers();
expect(intervals).toBe(3);
expect(jest.getTimerCount()).toBe(0);
let nested = 0;
setTimeout(() => { nested++; setTimeout(() => nested++, 10); }, 10);
vi.runOnlyPendingTimers();
expect(nested).toBe(1);
expect(jest.getTimerCount()).toBe(1);
vi.runAllTimers();
expect(nested).toBe(2);

expect(await realTimer).toBe("real");
const promised = promisedTimeout(0, "promise");
vi.advanceTimersByTime(0);
expect(await promised).toBe("promise");
setImmediate(() => events.push("immediate"));
vi.runAllTimers();
expect(events.at(-1)).toBe("immediate");
let immediateRuns = 0;
function repeatImmediate() {
  immediateRuns++;
  if (immediateRuns < 3) setImmediate(repeatImmediate);
}
setImmediate(repeatImmediate);
vi.runOnlyPendingTimers();
expect(immediateRuns).toBe(1);
vi.runAllTimers();
expect(immediateRuns).toBe(3);

let due = false;
setTimeout(() => due = true, 10);
vi.setSystemTime(-100);
vi.advanceTimersByTime(9);
expect(due).toBe(false);
expect(Date.now()).toBe(-91);
vi.advanceTimersByTime(1);
expect(due).toBe(true);
expect(Date.now()).toBe(-90);
vi.setSystemTime(0);
vi.advanceTimersByTime(0.993);
vi.advanceTimersByTime(0.5);
expect(Date.now()).toBe(1);
vi.clearAllTimers();
setTimeout(() => { throw new Error("discarded fake timer fired"); }, 10);
expect(vi.useRealTimers()).toBe(vi);
expect(Date.now()).toBeGreaterThanOrEqual(realBefore);
expect(Object.hasOwn(setTimeout, "clock")).toBe(false);
expect(Date).toBe(OriginalDate);
setSystemTime(-1);
expect(Date.now()).toBe(-1);
setSystemTime();
expect(Date.now()).toBeGreaterThanOrEqual(realBefore);
expect(() => jest.advanceTimersByTime(1)).toThrow("Fake timers");

let optionReads = 0;
jest.useFakeTimers({ get now() { optionReads++; return 0; } });
expect(optionReads).toBe(1);
let defaultDelay = false;
setTimeout(() => defaultDelay = true);
jest.advanceTimersByTime(0);
expect(defaultDelay).toBe(true);
expect(Date.now()).toBe(1);
const pending = setTimeout(() => { throw new Error("cleared timer fired"); }, 100);
jest.clearAllTimers();
pending.refresh();
expect(jest.getTimerCount()).toBe(0);
jest.setSystemTime(0);
expect(() => jest.advanceTimersByTime(-1)).toThrow();
expect(() => jest.advanceTimersByTime(Infinity)).toThrow();
expect(() => jest.setSystemTime(Infinity)).toThrow();
expect(() => jest.useFakeTimers({ now: NaN })).toThrow();
expect(jest.now()).toBe(0);
jest.useRealTimers();
await new Promise(resolve => setTimeout(resolve, 1));
console.log("fake timers ok");
